from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import requests


DEFAULT_BASE_URL = "https://aplikace.skolaonline.cz/solapi/api"
DEFAULT_SCOPE = "openid offline_access profile sol_api"
DEFAULT_CLIENT_ID = "test_client"


class SkolaOnlineError(RuntimeError):
    pass


@dataclass
class SkolaOnlineClient:
    username: str
    password: str
    base_url: str = DEFAULT_BASE_URL
    client_id: str = DEFAULT_CLIENT_ID
    scope: str = DEFAULT_SCOPE
    timeout_seconds: float = 20

    def __post_init__(self) -> None:
        self.base_url = self.base_url.rstrip("/")
        self.session = requests.Session()
        self.access_token: str | None = None
        self.refresh_token: str | None = None

    def login(self) -> dict[str, Any]:
        response = self.session.post(
            f"{self.base_url}/connect/token",
            data={
                "grant_type": "password",
                "client_id": self.client_id,
                "username": self.username,
                "password": self.password,
                "scope": self.scope,
            },
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            timeout=self.timeout_seconds,
        )
        token_data = self._json_or_raise(response, "login failed")

        access_token = token_data.get("access_token")
        if not access_token:
            raise SkolaOnlineError("login response did not include access_token")

        self.access_token = access_token
        self.refresh_token = token_data.get("refresh_token")
        return token_data

    def get_user(self) -> dict[str, Any]:
        return self.get("/v1/user")

    def get_marks(self, student_id: str, signing_filter: str = "all") -> dict[str, Any]:
        return self.get(
            f"/v1/students/{student_id}/marks/list",
            params={"SigningFilter": signing_filter},
        )

    def get(self, path: str, params: dict[str, Any] | None = None) -> dict[str, Any]:
        if not self.access_token:
            self.login()

        response = self.session.get(
            f"{self.base_url}{path}",
            params=params,
            headers={"Authorization": f"Bearer {self.access_token}"},
            timeout=self.timeout_seconds,
        )
        return self._json_or_raise(response, f"GET {path} failed")

    @staticmethod
    def _json_or_raise(response: requests.Response, message: str) -> dict[str, Any]:
        if response.ok:
            try:
                data = response.json()
            except ValueError as exc:
                raise SkolaOnlineError(f"{message}: response was not JSON") from exc
            if not isinstance(data, dict):
                raise SkolaOnlineError(f"{message}: expected JSON object")
            return data

        detail = response.text[:500].replace("\n", " ")
        raise SkolaOnlineError(f"{message}: HTTP {response.status_code}: {detail}")
